          ..data = ffi.nullptr;
        _uniFfiRustBufferFree(bufPtr.ref, freeStatusPtr);
        calloc.free(freeStatusPtr);
        calloc.free(bufPtr);
      }
      calloc.free(argBuf);
      calloc.free(returnBuf);
    }
  }
}

