final class PageFfiCodec {
  const PageFfiCodec._();

  static int lower(Page value) => value._handle;

  static Page lift(int handle) => Page._(_bindings(), handle);
}

final class _PluginHandleFinalizerToken {
  const _PluginHandleFinalizerToken(this.free, this.handle);
  final void Function(int) free;
  final int handle;
}

/// A handle to an enabled plugin, exposed to every language.
final class PluginHandle {
  PluginHandle._(this._ffi, this._handle) {
    _finalizer.attach(
        this, _PluginHandleFinalizerToken(_ffi._pluginHandleFree, _handle),
        detach: this);
  }

  final XcelerateFfi _ffi;
  int _handle;
  bool _closed = false;

  static final Finalizer<_PluginHandleFinalizerToken> _finalizer =
      Finalizer((token) {
    token.free(token.handle);
  });

  bool get isClosed => _closed;

  void close() {
    if (_closed) {
      return;
    }
    _closed = true;
    _finalizer.detach(this);
    _ffi._pluginHandleFree(_handle);
  }

  void _ensureOpen() {
    if (_closed) {
      throw StateError('PluginHandle is closed');
    }
  }

  /// Invoke an op with a JSON-encoded argument object; returns JSON.
  Future<String> invoke(String op, String argsJson) {
    _ensureOpen();
    return _ffi.pluginHandleInvokeInvoke(_handle, op, argsJson);
  }

  /// The ops this plugin exposes.
  List<String> ops() {
    _ensureOpen();
    return _ffi.pluginHandleInvokeOps(_handle);
  }

  /// The plugin's name.
  String pluginName() {
    _ensureOpen();
    return _ffi.pluginHandleInvokePluginName(_handle);
  }
}

final class PluginHandleFfiCodec {
  const PluginHandleFfiCodec._();

  static int lower(PluginHandle value) => value._handle;

  static PluginHandle lift(int handle) => PluginHandle._(_bindings(), handle);
}

XcelerateFfi? _defaultBindings;

XcelerateFfi _bindings() => _defaultBindings ??= XcelerateFfi();

void configureDefaultBindings(
    {ffi.DynamicLibrary? dynamicLibrary, String? libraryPath}) {
  _defaultBindings =
      XcelerateFfi(dynamicLibrary: dynamicLibrary, libraryPath: libraryPath);
}

void resetDefaultBindings() {
  _defaultBindings = null;
}
